}

/* Helper function for addReplyCommand() to output flags. */
int addReplyCommandFlag(client *c, uint64_t flags, uint64_t f, char *reply) {
    if (flags & f) {
        addReplyStatus(c, reply);
        return 1;
    }
    return 0;
}

